    split; [apply AG; [exact G3| cbn; unfold RPAGE_SIZE; lia]|]. split; [apply AG; [exact G4| cbn; unfold RGOT_SSP; lia]|]. apply AG; [exact G5| cbn; unfold RSSP_GUARD; lia].
