    - eapply unk_agree_munch; [exact UA1| exact MU| |].
      + intros rid r Hr Hk. pose proof (rregion_facts st1 m1 rid r MR1 Hr) as (R1 & _ & R2 & _). pose proof (rregion_facts_hi st1 m1 rid r MR1 Hr) as R3. unfold OSSVerify.Proofs.zlib.example_small_fuzzer.lib.ubsan_halts_any_exit.Spec.Malloc.MCEIL in R2; try (pose proof ceil_window_holds as CEIL_RANGE__); unfold ceil_window in *. cbn. lia.
      + intros rid r Hr. pose proof (rregion_facts st1 m1 rid r MR1 Hr) as (R1 & _ & R2 & _). unfold OSSVerify.Proofs.zlib.example_small_fuzzer.lib.ubsan_halts_any_exit.Spec.Malloc.MCEIL in R2; try (pose proof ceil_window_holds as CEIL_RANGE__); unfold ceil_window in *. lia. }
  destruct ans as [e|xa].
  -
    cbn [rmmap_anon_post] in PO.
